class Solution {
    public boolean isSameTree(TreeNode p, TreeNode q) {
        List<String> lp = new ArrayList<>(), lq = new ArrayList<>();
        serialize(p, lp); serialize(q, lq);
        if (lp.size() != lq.size()) return false;
        for (int i = 0; i < lp.size(); i++)
            if (!lp.get(i).equals(lq.get(i))) return false;
        return true;
    }
    void serialize(TreeNode n, List<String> out) {
        if (n == null) { out.add("#"); return; }
        out.add(String.valueOf(n.val));
        serialize(n.left, out); serialize(n.right, out);
    }
}

class Solution {
    public boolean isSameTree(TreeNode p, TreeNode q) {
        Queue<TreeNode> qp = new LinkedList<>(), qq = new LinkedList<>();
        qp.offer(p); qq.offer(q);
        while (!qp.isEmpty()) {
            TreeNode a = qp.poll(), b = qq.poll();
            if (a == null && b == null) continue;     // 都空，继续看下一对
            if (a == null || b == null) return false; // 一空一有，结构不同
            if (a.val != b.val) return false;         // 值不同
            qp.offer(a.left);  qp.offer(a.right);
            qq.offer(b.left);  qq.offer(b.right);
        }
        return true;
    }
}

class Solution {
    public boolean isSameTree(TreeNode p, TreeNode q) {
        if (p == null && q == null) return true;   // 都空：这一支相同
        if (p == null || q == null) return false;  // 一空一有：结构不同
        if (p.val != q.val) return false;          // 值不同
        return isSameTree(p.left, q.left)
            && isSameTree(p.right, q.right);
    }
}

