isMirror(a, b):
    if a == null && b == null: return true      // 都空，对称
    if a == null || b == null: return false     // 一空一有，不对称
    if a.val != b.val: return false             // 值不同，不对称
    // 核心：交叉比较
    return isMirror(a.left, b.right) && isMirror(a.right, b.left)

/**
 * 对称二叉树 —— 递归交叉比较，O(n) 时间，O(h) 空间（h 为树高）
 */
class Solution {
    public boolean isSymmetric(TreeNode root) {
        if (root == null) return true;
        return isMirror(root.left, root.right);
    }

    private boolean isMirror(TreeNode a, TreeNode b) {
        if (a == null && b == null) return true;   // 都空 → 对称
        if (a == null || b == null) return false;  // 一空一有 → 不对称
        if (a.val != b.val) return false;          // 值不同 → 不对称
        // 交叉比较：a 左比 b 右，a 右比 b 左
        return isMirror(a.left, b.right) && isMirror(a.right, b.left);
    }
}

/**
 * 对称二叉树 —— 层序迭代，O(n) 时间，O(n) 空间（队列）
 */
class Solution {
    public boolean isSymmetric(TreeNode root) {
        if (root == null) return true;
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root.left);
        queue.offer(root.right);
        while (!queue.isEmpty()) {
            TreeNode a = queue.poll();
            TreeNode b = queue.poll();
            if (a == null && b == null) continue;   // 都空，继续下一对
            if (a == null || b == null) return false;
            if (a.val != b.val) return false;
            // 交叉入队：a.left↔b.right，a.right↔b.left
            queue.offer(a.left);
            queue.offer(b.right);
            queue.offer(a.right);
            queue.offer(b.left);
        }
        return true;
    }
}

