// 官方解法：力扣标准答案（快慢指针 swap，原地）
// 时间 O(n)，空间 O(1)
// 作者：力扣官方题解
class Solution {
    public void moveZeroes(int[] nums) {
        int n = nums.length, left = 0, right = 0;
        while (right < n) {
            if (nums[right] != 0) {
                swap(nums, left, right);
                left++;
            }
            right++;
        }
    }

    public void swap(int[] nums, int left, int right) {
        int temp = nums[left];
        nums[left] = nums[right];
        nums[right] = temp;
    }
}

// 我的原稿：双指针压缩（两遍扫描，原地）
class Solution {
    public void moveZeroes(int[] nums) {
        if (nums == null) {
            return;
        }
        // 第一遍：j 记录非零个数，把所有非零依次前移
        int j = 0;
        for (int i = 0; i < nums.length; ++i) {
            if (nums[i] != 0) {
                nums[j++] = nums[i];
            }
        }
        // 非零点统计完，[j, n) 全是 0，第二遍补 0
        for (int i = j; i < nums.length; ++i) {
            nums[i] = 0;
        }
    }
}

