// 官方解法：力扣标准答案
// 时间 O(n+m)（拼接比较 + 截取），空间 O(n+m)（拼接出的新串）
// 作者：力扣官方题解
class Solution {
    public String gcdOfStrings(String str1, String str2) {
        if (!str1.concat(str2).equals(str2.concat(str1))) {
            return "";
        }
        return str1.substring(0, gcd(str1.length(), str2.length()));
    }

    public int gcd(int a, int b) {
        int remainder = a % b;
        while (remainder != 0) {
            a = b;
            b = remainder;
            remainder = a % b;
        }
        return b;
    }
}

// 我的原稿：思路与官方等价 —— 先判 str1+str2 是否等于 str2+str1，再截 gcd 前缀
class Solution {
    public String gcdOfStrings(String str1, String str2) {
        // 先判断有没有解
        if (!(str1 + str2).equals(str2 + str1)) {
            return "";
        }

        return str1.substring(0, gcd(str1.length(), str2.length()));
    }

    public int gcd(int a, int b) {
        int x = a % b;
        while (x != 0) {
            a = b;
            b = x;
            x = a % b;
        }
        return b;
    }
}

